import{_ as a,o as e,c as d,ag as r}from"./chunks/framework.C5oN-8Wt.js";const s="/cns_master_docs/teaching-v0.4.0-alpha/02-wave-quantities.svg",b=JSON.parse('{"title":"02 用高低、快慢和起点描述信号","description":"","frontmatter":{},"headers":[],"relativePath":"v0.4.0-alpha/learn/02-wave-quantities/index.md","filePath":"v0.4.0-alpha/learn/02-wave-quantities/index.md"}'),n={name:"v0.4.0-alpha/learn/02-wave-quantities/index.md"};function o(i,t,l,h,p,c){return e(),d("div",null,[...t[0]||(t[0]=[r(`<h1 id="_02-用高低、快慢和起点描述信号" tabindex="-1">02 用高低、快慢和起点描述信号 <a class="header-anchor" href="#_02-用高低、快慢和起点描述信号" aria-label="Permalink to &quot;02 用高低、快慢和起点描述信号&quot;">​</a></h1><p>适用 <strong>v0.4.0-alpha</strong>。先会读<a href="./../01-link-overview/">01 的时域坐标</a>，本课只需乘除和角度常识。</p><h2 id="低空应用问题与学习目标" tabindex="-1">低空应用问题与学习目标 <a class="header-anchor" href="#低空应用问题与学习目标" aria-label="Permalink to &quot;低空应用问题与学习目标&quot;">​</a></h2><p>机地通信要用可区分的信号表示信息。如果只说“波形变了”，接收端很难知道究竟变了什么。本课用两路同样的正弦波建立参照，再分别认识<strong>幅度、频率、相位</strong>，为调制实验准备词汇。</p><p>周期 T 是重复一次所需的时间，单位秒；频率 f 是每秒重复的次数，单位 Hz，<code>T = 1/f</code>。幅度描述相对中线的最大偏离，不能把峰到谷的差值叫作幅度。相位描述一个周期内所处的位置：整圈 360° 对应 <strong>2π rad</strong>，四分之一圈为 <strong>π/2 rad ≈ 1.570796 rad</strong>；rad 是弧度单位。</p><h2 id="接线与参数理由" tabindex="-1">接线与参数理由 <a class="header-anchor" href="#接线与参数理由" aria-label="Permalink to &quot;接线与参数理由&quot;">​</a></h2><p><a href="../../../downloads/teaching-v0.4.0-alpha/02-wave-quantities.cnsproj" download>下载 02-wave-quantities.cnsproj</a></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1 out ──→ 观察器：参照波</span></span>
<span class="line"><span>信号源 2 out ──→ 观察器：实验波</span></span></code></pre></div><p>两路不相加，各自直接观察。同一软件运行中以各自第 0 个样本为起点；这不是两台独立无线设备已经完成同步。</p><table tabindex="0"><thead><tr><th>两个源的初始设置</th><th>数值</th><th>原因</th></tr></thead><tbody><tr><td>波形／幅度／偏置</td><td>正弦／1／0</td><td>让中线为 0，区分幅度与偏置。</td></tr><tr><td>频率</td><td>64 Hz</td><td>周期 1/64 s = 15.625 ms。1 ms = 0.001 s。</td></tr><tr><td>初相位</td><td>0 rad</td><td>起初两路重合，便于与后来的变化比较。</td></tr><tr><td>采样率</td><td>1024 sample/s</td><td>每周期 16 点，本课不同时改变取样疏密。</td></tr></tbody></table><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>打开下载工程；在观察器参数页确认信号源 1、2 的 <code>out</code>。需要叠加时，用“添加捕获变量”选第二路，模式为时域叠加。</li><li>设每路 <strong>4096</strong> 样本，按 <strong>F5</strong>。停止后将横轴缩到约 <strong>0.0625 s</strong>，应见四周期；纵轴先自动，读出 ±1。</li><li>记录基准图：两路周期相同且重合。若要按样本起点比较相位，查看从 0 s 开始的数据，或比较同一时刻的两个波峰，别把拖动窗口造成的平移当成相位改变。</li><li>按下面顺序做三次对照。每次先停止、恢复信号源 2 的初始值，再只改一个字段，重新 F5。信号源 1 始终保持初始值。</li><li>用“另存为”保存自己的一个对照版本；记录修改字段、轴刻度与解释。</li></ol><h2 id="用-a-b-游标读周期与峰峰值" tabindex="-1">用 A／B 游标读周期与峰峰值 <a class="header-anchor" href="#用-a-b-游标读周期与峰峰值" aria-label="Permalink to &quot;用 A／B 游标读周期与峰峰值&quot;">​</a></h2><p>在观察器时域图点击“测量”，将 A、B 都选为实验波。拖动游标手柄，让它们吸附相邻周期的同相位样本：64 Hz 的一周期应约为 15.625 ms。再选择同一周期的峰和谷，读取两点数值差；幅度为 1 时，峰峰值约为 2。游标读取离散真实样本，不自动寻找峰或判定周期。</p><p>测量时波形定格，实验继续运行；点击“自动刻度”可清除测量并返回实时观看。测量位置不写入工程。</p><h2 id="单参数对照与预期图像" tabindex="-1">单参数对照与预期图像 <a class="header-anchor" href="#单参数对照与预期图像" aria-label="Permalink to &quot;单参数对照与预期图像&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.4.0-alpha/02-wave-quantities.svg"><img src="`+s+'" alt="实际 GNU 数据：同相波重合，幅度改为 0.5 后峰值降低而周期不变"></a></p><p>本图显示基准和“只改幅度”的实际对照；后面的频率、相位练习分别重跑，不是在这一轮中同时改变三项。</p><table tabindex="0"><thead><tr><th>每次只改信号源 2 的一项</th><th>先预测，再核对</th></tr></thead><tbody><tr><td>幅度 1 → <strong>0.5</strong></td><td>峰谷约 ±0.5，周期仍 15.625 ms，过零位置与参照相同。</td></tr><tr><td>频率 64 → <strong>128 Hz</strong></td><td>同一段 0.0625 s 内由 4 周期变为 8 周期，幅度仍约 1。</td></tr><tr><td>初相位 0 → <strong>π/2 rad</strong></td><td>频率仍 64 Hz，初始样本从 0 变为约 +1；实验波相对参照提前四分之一周期，即 3.90625 ms。</td></tr></tbody></table><p>正相位使本例的正弦在同一时刻更早走到峰值。若把相位看成“横向移动”，必须同时说明比较参照与方向。<strong>恒定相位差不改变频率</strong>；下一课会看到取样点也会改变折线外观。</p><p>也可用公式检查：<code>x(t) = A × sin(2πft + φ) + offset</code>。不必先会推导，只要对应 A 为幅度、f 为 Hz、t 为 s、φ 为 rad；例如 t=0、φ=π/2 时，sin(π/2)=1。公式描述本课理想正弦，不把所有通信波形都当成一条正弦。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>解释与处理</th></tr></thead><tbody><tr><td>相位填 90 后现象不对</td><td>字段单位是 rad，90° 应填约 1.570796，90 rad 不是四分之一圈。</td></tr><tr><td>把幅度 1 读成 2</td><td>从 −1 到 +1 是峰峰值 2，幅度仍是 1。</td></tr><tr><td>改相位后频谱主峰仍在 64 Hz</td><td>恒定相位只改起点，本课幅度谱不显示该相位差。</td></tr><tr><td>改频率后峰值略低于 1</td><td>样本未必恰好落在峰顶；先读每周期点数，不把折线最大值当成连续波的精确峰值。</td></tr><tr><td>改草稿后曲线没变</td><td>本课统一停止再运行，不用旧缓存判断新参数是否生效。</td></tr></tbody></table><p><a href="./../../modules/signal_source/">信号源完整参数</a> · <a href="./../">返回学习路径</a> · <a href="./../03-sampling/">下一课：采样 →</a></p>',24)])])}const u=a(n,[["render",o]]);export{b as __pageData,u as default};
